/**
 * Library の絞り込み。UI/UX §10.1「Filters: Project / Person / Date / Generated by / Sensitivity」。
 *
 * 選択肢は**手元の成果物から**組む。無い選択肢は出さない（空の選択肢は嘘に近い）。
 * Project / Person は Phase 6（World Model）まで entities が空なので、
 * `project:` / `person:` の tag から拾う。無ければその絞り込みは「まだありません」。
 */
import type { Artifact } from '@astra/contracts';

export type DateRange = 'all' | 'today' | '7d' | '30d';

export interface LibraryFilters {
  readonly project: string | null;
  readonly person: string | null;
  readonly date: DateRange;
  /** source_agent_id。null = すべて、'manual' = 手で追加したもの */
  readonly generatedBy: string | null;
  readonly sensitivity: Artifact['sensitivity'] | null;
}

export const EMPTY_FILTERS: LibraryFilters = {
  project: null,
  person: null,
  date: 'all',
  generatedBy: null,
  sensitivity: null,
};

export const DATE_RANGES: { id: DateRange; label: string }[] = [
  { id: 'all', label: 'すべての期間' },
  { id: 'today', label: '今日' },
  { id: '7d', label: '7 日以内' },
  { id: '30d', label: '30 日以内' },
];

/** 人の言葉。agent の id をそのまま出さない。 */
const AGENT_LABEL: Record<string, string> = {
  research: '調べもの',
  meeting: '会議',
  general: 'アシスタント',
  assistant: 'アシスタント',
  echo: '試し',
};

export function generatedByLabel(agentId: string | null | undefined): string {
  if (agentId === null || agentId === undefined) return '手で追加';
  // 「com.astra.research」→「research」。逆ドメインの末尾が agent の名前
  const short = agentId.split('.').pop() ?? agentId;
  return AGENT_LABEL[short] ?? short;
}

function tagged(artifacts: readonly Artifact[], prefix: string): string[] {
  const values = new Set<string>();
  for (const a of artifacts) {
    for (const tag of a.tags) if (tag.startsWith(prefix)) values.add(tag.slice(prefix.length));
  }
  return [...values].sort();
}

export interface FilterOptions {
  readonly projects: readonly string[];
  readonly people: readonly string[];
  readonly generatedBy: readonly { id: string; label: string }[];
  readonly sensitivities: readonly Artifact['sensitivity'][];
}

export function filterOptions(artifacts: readonly Artifact[]): FilterOptions {
  const agents = new Map<string, string>();
  for (const a of artifacts) {
    const id = a.source_agent_id ?? 'manual';
    agents.set(id, generatedByLabel(a.source_agent_id));
  }
  const sensitivities = [...new Set(artifacts.map((a) => a.sensitivity))].filter(
    (s) => s !== 'PRIVATE',
  );
  return {
    projects: tagged(artifacts, 'project:'),
    people: tagged(artifacts, 'person:'),
    generatedBy: [...agents].map(([id, label]) => ({ id, label })),
    sensitivities,
  };
}

function withinDate(iso: string, range: DateRange, now: number): boolean {
  if (range === 'all') return true;
  const at = Date.parse(iso);
  if (range === 'today') {
    const d = new Date(now);
    const start = new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
    return at >= start;
  }
  const days = range === '7d' ? 7 : 30;
  return now - at <= days * 86_400_000;
}

export function matchesFilters(
  artifact: Artifact,
  filters: LibraryFilters,
  now: number = Date.now(),
): boolean {
  if (filters.project && !artifact.tags.includes(`project:${filters.project}`)) return false;
  if (filters.person && !artifact.tags.includes(`person:${filters.person}`)) return false;
  if (!withinDate(artifact.created_at, filters.date, now)) return false;
  if (filters.generatedBy) {
    const id = artifact.source_agent_id ?? 'manual';
    if (id !== filters.generatedBy) return false;
  }
  if (filters.sensitivity && artifact.sensitivity !== filters.sensitivity) return false;
  return true;
}

export function activeFilterCount(filters: LibraryFilters): number {
  return (
    (filters.project ? 1 : 0) +
    (filters.person ? 1 : 0) +
    (filters.date !== 'all' ? 1 : 0) +
    (filters.generatedBy ? 1 : 0) +
    (filters.sensitivity ? 1 : 0)
  );
}

/** §10.2 の「Derived from …」。親を辿れる範囲で、近い順。 */
export function lineageOf(
  artifact: Artifact,
  all: readonly Artifact[],
  limit = 5,
): readonly Artifact[] {
  const byId = new Map(all.map((a) => [a.id, a]));
  const chain: Artifact[] = [];
  let cursor = artifact.parent_artifact_id ? byId.get(artifact.parent_artifact_id) : undefined;
  const seen = new Set<string>([artifact.id]);
  while (cursor && !seen.has(cursor.id) && chain.length < limit) {
    chain.push(cursor);
    seen.add(cursor.id);
    cursor = cursor.parent_artifact_id ? byId.get(cursor.parent_artifact_id) : undefined;
  }
  return chain;
}
